//! Oracle rows and real packet builders for the rig / image-mesh producer (L07-L; I16a, G03a).
//!
//! `fixtures/object-scene-producer-rig/oracle.txt` was generated by `tools/gen_rig.cjs` from
//! baseline fbe4b8a3: the verbatim `applyRigDeform` over real Paper.js, then the real
//! `SMImageMesh.scenePayloadFor`. Numbers are JS `String(n)`, compared with `==`.
//! * `MESH name rect img op verts offs tris outlineN bones rest weights pose => V U T O | NONE`
//! * `STROKE name bones rest rh weights live => SEGS | skip`
//! Points are `x,y`, point lists `P;P;..` or `_`, bones `id/closed/live/rest` joined by `|`,
//! weights `bone:pt:w;..` per vertex joined by `|`. A stroke segment is `P[~hi][^ho]`
//! (only the handles the baseline wrote).

use super::{MeshSource, PoseTarget};
use crate::evaluation::object_image_mesh_kernels::object_image_mesh_geometry::{
    MeshRect, MeshView,
};
use crate::evaluation::object_image_mesh_kernels::rig_pose_deform::{PathBind, RestHandle};
use crate::evaluation::object_image_mesh_kernels::rig_pose_deform_anchor::{
    DeformBone, DeformSegment,
};
use crate::evaluation::object_image_mesh_kernels::rig_pose_weights::{
    ControlWeight, Point2, WeightEntry,
};

pub(crate) const ORACLE: &str = include_str!("fixtures/object-scene-producer-rig/oracle.txt");

fn num(tok: &str) -> f64 {
    tok.parse::<f64>().expect("number token")
}

pub(crate) fn pt(tok: &str) -> Point2 {
    let (x, y) = tok.split_once(',').expect("x,y");
    [num(x), num(y)]
}

pub(crate) fn pts(tok: &str) -> Vec<Point2> {
    if tok == "_" {
        Vec::new()
    } else {
        tok.split(';').map(pt).collect()
    }
}

fn indices(tok: &str) -> Vec<u32> {
    if tok == "_" {
        Vec::new()
    } else {
        tok.split(',').map(|t| t.parse().expect("index")).collect()
    }
}

fn dseg(point: Point2) -> DeformSegment {
    DeformSegment {
        point: Some(point),
        handle_in: None,
        handle_out: None,
    }
}

pub(crate) fn bones(tok: &str) -> Vec<DeformBone> {
    if tok == "-" {
        return Vec::new();
    }
    tok.split('|')
        .map(|bone| {
            let f: Vec<&str> = bone.split('/').collect();
            assert_eq!(f.len(), 4, "{bone}");
            DeformBone {
                id: f[0].to_owned(),
                closed: f[1] == "1",
                segments: Some(pts(f[2]).into_iter().map(dseg).collect()),
                rest_segments: Some(pts(f[3]).into_iter().map(dseg).collect()),
            }
        })
        .collect()
}

pub(crate) fn weights(tok: &str) -> Vec<Vec<WeightEntry>> {
    if tok == "-" {
        return Vec::new();
    }
    tok.split('|')
        .map(|list| {
            if list == "_" {
                return Vec::new();
            }
            list.split(';')
                .map(|entry| {
                    let f: Vec<&str> = entry.split(':').collect();
                    assert_eq!(f.len(), 3, "{entry}");
                    WeightEntry::Control(ControlWeight {
                        bone_id: f[0].to_owned(),
                        pt_index: f[1].parse().expect("control point index"),
                        w: num(f[2]),
                        stray_offset: None,
                    })
                })
                .collect()
        })
        .collect()
}

pub(crate) struct Expected {
    pub(crate) verts: Vec<Point2>,
    pub(crate) uvs: Vec<Point2>,
    pub(crate) tris: Vec<u32>,
    pub(crate) outline: usize,
}

pub(crate) struct MeshCase {
    pub(crate) name: String,
    pub(crate) bones_tok: String,
    pub(crate) rect: MeshRect,
    pub(crate) img: (u32, u32),
    pub(crate) op: f32,
    pub(crate) verts: Vec<Point2>,
    pub(crate) offs: Vec<Point2>,
    pub(crate) tris: Vec<u32>,
    pub(crate) outline: Vec<Point2>,
    pub(crate) bones: Vec<DeformBone>,
    pub(crate) rest: Vec<Point2>,
    pub(crate) weights: Vec<Vec<WeightEntry>>,
    pub(crate) pose: Option<Vec<Option<Point2>>>,
    pub(crate) expected: Option<Expected>,
}

impl MeshCase {
    pub(crate) fn source(&self) -> MeshSource<'_> {
        MeshSource {
            mesh: MeshView {
                outline: &self.outline,
                verts: &self.verts,
                offsets: &self.offs,
                tris: &self.tris,
            },
            rect: self.rect,
            image_width: self.img.0,
            image_height: self.img.1,
            opacity: self.op,
            pose: self.pose.as_deref(),
        }
    }

    pub(crate) fn target(&self, index: usize) -> PoseTarget<'_> {
        if self.bones.is_empty() {
            PoseTarget::Mesh {
                source_object_index: index,
                source: self.source(),
            }
        } else {
            PoseTarget::RigMesh {
                source_object_index: index,
                rest: &self.rest,
                weights: &self.weights,
                rotate: false,
                source: self.source(),
            }
        }
    }
}

pub(crate) struct ExpSeg {
    pub(crate) point: Point2,
    pub(crate) hi: Option<Point2>,
    pub(crate) ho: Option<Point2>,
}

pub(crate) struct StrokeCase {
    pub(crate) name: String,
    pub(crate) bones_tok: String,
    pub(crate) bones: Vec<DeformBone>,
    pub(crate) rest: Vec<Point2>,
    pub(crate) rh: Option<Vec<RestHandle>>,
    pub(crate) weights: Vec<Vec<WeightEntry>>,
    pub(crate) live: Option<usize>,
    pub(crate) expected: Option<Vec<ExpSeg>>,
}

impl StrokeCase {
    pub(crate) fn target(&self, index: usize) -> PoseTarget<'_> {
        PoseTarget::RigStroke {
            source_object_index: index,
            bind: PathBind {
                rest: &self.rest,
                rest_handles: self.rh.as_deref(),
                weights: &self.weights,
                rotate: false,
                live_len: self.live,
                center: None,
            },
        }
    }
}

fn opt_pt(tok: &str) -> Option<Point2> {
    (tok != "-").then(|| pt(tok))
}

fn rest_handles(tok: &str) -> Option<Vec<RestHandle>> {
    if tok == "!" {
        return None;
    }
    Some(
        tok.split(';')
            .map(|entry| {
                let (hi, ho) = entry.split_once('/').expect("I/O");
                RestHandle {
                    handle_in: opt_pt(hi),
                    handle_out: opt_pt(ho),
                }
            })
            .collect(),
    )
}

fn segments(tok: &str) -> Vec<ExpSeg> {
    if tok == "_" {
        return Vec::new();
    }
    tok.split(';')
        .map(|seg| {
            let (head, ho) = match seg.split_once('^') {
                Some((head, ho)) => (head, Some(pt(ho))),
                None => (seg, None),
            };
            let (point, hi) = match head.split_once('~') {
                Some((point, hi)) => (pt(point), Some(pt(hi))),
                None => (pt(head), None),
            };
            ExpSeg { point, hi, ho }
        })
        .collect()
}

pub(crate) fn mesh_cases() -> Vec<MeshCase> {
    ORACLE
        .lines()
        .filter(|line| line.starts_with("MESH "))
        .map(|line| {
            let f: Vec<&str> = line.split(' ').collect();
            let r: Vec<f64> = f[2].split(',').map(num).collect();
            let img: Vec<u32> = f[3].split(',').map(|t| t.parse().unwrap()).collect();
            let verts = pts(f[5]);
            let outline_n: usize = f[8].parse().unwrap();
            assert_eq!(f[13], "=>", "{line}");
            let expected = (f[14] != "NONE").then(|| Expected {
                verts: pts(f[14]),
                uvs: pts(f[15]),
                tris: indices(f[16]),
                outline: f[17].parse().unwrap(),
            });
            MeshCase {
                name: f[1].to_owned(),
                bones_tok: f[9].to_owned(),
                rect: MeshRect {
                    x: r[0],
                    y: r[1],
                    width: r[2],
                    height: r[3],
                    rotation: r[4],
                },
                img: (img[0], img[1]),
                op: f[4].parse().unwrap(),
                outline: verts[..outline_n].to_vec(),
                verts,
                offs: pts(f[6]),
                tris: indices(f[7]),
                bones: bones(f[9]),
                rest: if f[10] == "-" { Vec::new() } else { pts(f[10]) },
                weights: weights(f[11]),
                pose: (f[12] != "-").then(|| {
                    f[12]
                        .split(';')
                        .map(opt_pt)
                        .collect::<Vec<Option<Point2>>>()
                }),
                expected,
            }
        })
        .collect()
}

pub(crate) fn stroke_cases() -> Vec<StrokeCase> {
    ORACLE
        .lines()
        .filter(|line| line.starts_with("STROKE "))
        .map(|line| {
            let f: Vec<&str> = line.split(' ').collect();
            assert_eq!(f[7], "=>", "{line}");
            StrokeCase {
                name: f[1].to_owned(),
                bones_tok: f[2].to_owned(),
                bones: bones(f[2]),
                rest: pts(f[3]),
                rh: rest_handles(f[4]),
                weights: weights(f[5]),
                live: (f[6] != "!").then(|| f[6].parse().unwrap()),
                expected: (f[8] != "skip").then(|| segments(f[8])),
            }
        })
        .collect()
}

pub(crate) fn mesh_case(name: &str) -> MeshCase {
    mesh_cases()
        .into_iter()
        .find(|case| case.name == name)
        .unwrap_or_else(|| panic!("no MESH row {name}"))
}

pub(crate) fn stroke_case(name: &str) -> StrokeCase {
    stroke_cases()
        .into_iter()
        .find(|case| case.name == name)
        .unwrap_or_else(|| panic!("no STROKE row {name}"))
}
